            {
              "_id": "6b81968e-3744-4416-9d64-74547eb0a7d1",
              "attribute": "groups",
              "op": "in",
              "values": ["Top Customers"],
              "contextKind": "user",
              "negate": false
            },
            {
              "_id": "9d60165d-82b8-4b9a-9136-f23407ba1718",
              "attribute": "email",
              "op": "endsWith",
              "values": ["gmail.com"],
